held=[r['env_kwargs'] for r in pq.read_table(root/'verl/test.parquet').to_pylist()]; scenarios={r['scenario'] for r in held}
def rows(fn):return [json.loads(l) for l in (root/(fn+'.jsonl')).read_text().splitlines()]
dbs={r['scenario']:r for r in rows('gen_db') if r['scenario'] in scenarios};samples={r['scenario']:r for r in rows('gen_sample') if r['scenario'] in scenarios}
vers={(r['scenario'],r['task_idx']):(ln,r) for ln,r in enumerate(rows('gen_verifier.pure_code'),1)}
# Recreate fixtures only in RAM; verifier connections cannot reach any file.
conns={}; errors=collections.Counter()
for sc in sorted(scenarios):
 con=sqlite3.connect(':memory:')
 def auth(action,a,b,c,d):
  return sqlite3.SQLITE_DENY if action in {sqlite3.SQLITE_ATTACH,sqlite3.SQLITE_DETACH} or (action==sqlite3.SQLITE_FUNCTION and b=='load_extension') else sqlite3.SQLITE_OK
 con.set_authorizer(auth)
 for t in dbs[sc]['db_schema']['tables']:
  try:
   con.execute(t['ddl'])
   for sql in t.get('indexes',[])+t.get('examples',[]):con.execute(sql)
  except Exception as e:errors['schema']+=1
 con.commit();con.execute('PRAGMA foreign_keys=ON')
 for t in samples[sc]['sample_data']['tables']:
  for sql in t['insert_statements']:
   try:con.execute(sql)
   except Exception as e:errors['insert']+=1
 con.commit();con.execute('PRAGMA query_only=ON');conns[sc]=con
orig_import=builtins.__import__; complete=[];results=collections.Counter()
for item in held:
 sc,ti=item['scenario'],item['task_idx'];ln,r=vers[(sc,ti)];con=conns[sc]
 class View:
  def cursor(self):return con.cursor()
  def execute(self,*args,**kw):return con.execute(*args,**kw)
  def close(self):pass
 proxy=types.ModuleType('sqlite3');proxy.connect=lambda *a,**kw:View()
 for attr in ['Row','Error','OperationalError','IntegrityError']:setattr(proxy,attr,getattr(sqlite3,attr))
 def imports(name,*args,**kw):
  if name=='sqlite3':return proxy
  if name not in {'re','json','datetime'}:raise ImportError(name)
  return orig_import(name,*args,**kw)
 safe_builtins=dict(vars(builtins));safe_builtins['__import__']=imports
 for attr in ['open','eval','exec','compile','input']:safe_builtins.pop(attr,None)
 ns={'__builtins__':safe_builtins}
 try:
  exec(r['verification']['code'],ns);f=next(v for k,v in ns.items() if k.startswith('verify_'));ret=f('initial','final','No actions performed.')
 except Exception as e:ret={'result':'error','error':str(e)}
 results[ret.get('result')]+=1
 if ret.get('result')=='complete':complete.append((sc,ti,ln,item['task']))
print('RAM_FIXTURE_CHECK',dict(results),'reset_errors',dict(errors),'date-sensitive SQL uses current clock; diagnostic only, not model evaluation')
for case in complete[:12]:print('NO_ACTION_COMPLETE',case)
for con in conns.values():con.close()
